package publicapi

import (
	_ "embed"
	"encoding/json"
)

//go:embed public_catalog_openapi.json
var publicCatalogOpenAPIJSON []byte

// buildCatalogPublicPaths returns the public, no-auth routes documented in the
// JEOS route catalog as an OpenAPI paths object. The data is loaded from the
// embedded JSON artifact generated by scripts/generate_openapi_public_catalog_json.py.
func buildCatalogPublicPaths() map[string]any {
	var paths map[string]any
	if err := json.Unmarshal(publicCatalogOpenAPIJSON, &paths); err != nil {
		// A broken JSON artifact is a build/packaging issue; return an empty map
		// so the rest of the spec is still served.
		return map[string]any{}
	}

	return paths
}
